
import java.util.*;

class Solution {
    public int maximumSaleItems(int[][] items, int budget) {
        int n = items.length;

        // Calculate the total free copies generated by each item.
        int[] reward = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && items[j][0] % items[i][0] == 0) {
                    reward[i]++;
                }
            }
        }

        // Group items by price.
        List<Integer>[] groups = new ArrayList[budget + 1];

        for (int i = 0; i <= budget; i++) {
            groups[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            int price = items[i][1];

            if (price <= budget) {
                groups[price].add(i);
            }
        }

        final int NEG = Integer.MIN_VALUE / 2;

        // dp[c] = maximum reward using items with
        // prices strictly greater than the current price.
        int[] dp = new int[budget + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;

        int answer = 0;

        // Process prices in descending order.
        for (int price = budget; price >= 1; price--) {

            if (groups[price].isEmpty()) {
                continue;
            }

            // DP requiring at least one item of current price.
            int[] current = new int[budget + 1];
            Arrays.fill(current, NEG);

            for (int idx : groups[price]) {
                int weight = 1 + reward[idx];

                for (int cost = budget; cost >= price; cost--) {

                    // Select this item as the first item
                    // from the current price group.
                    if (dp[cost - price] != NEG) {
                        current[cost] = Math.max(
                            current[cost],
                            dp[cost - price] + weight
                        );
                    }

                    // Select this item along with previously
                    // selected items from the current group.
                    if (current[cost - price] != NEG) {
                        current[cost] = Math.max(
                            current[cost],
                            current[cost - price] + weight
                        );
                    }
                }
            }

            // Add unlimited additional copies of the cheapest
            // selected item.
            for (int cost = price; cost <= budget; cost++) {
                if (current[cost] != NEG) {
                    int extraCopies = (budget - cost) / price;

                    answer = Math.max(
                        answer,
                        current[cost] + extraCopies
                    );
                }
            }

            // Merge the current price group into normal knapsack DP.
            for (int idx : groups[price]) {
                int weight = 1 + reward[idx];

                for (int cost = budget; cost >= price; cost--) {
                    if (dp[cost - price] != NEG) {
                        dp[cost] = Math.max(
                            dp[cost],
                            dp[cost - price] + weight
                        );
                    }
                }
            }
        }

        return answer;
    }
}
